window.TIMELINE = {"fps": 25, "scenes": [{"id": "hook", "title": "L'accroche", "start": 0.0, "beats": [{"id": "h_24", "start": 1.2, "end": 12.26, "sentences": [{"start": 1.2, "end": 3.9, "text": "Prenons un cabinet de gestion de patrimoine fictif."}, {"start": 4.08, "end": 12.26, "text": "Il passe environ vingt-quatre heures par semaine à rechercher des informations, préparer des rendez-vous, vérifier des pièces et reconstruire ses suivis clients."}]}, {"id": "h_10", "start": 12.6, "end": 20.92, "sentences": [{"start": 12.6, "end": 20.92, "text": "Sur ces vingt-quatre heures, notre hypothèse est qu'il pourrait en récupérer dix, sans laisser une intelligence artificielle conseiller à la place du CGP."}]}, {"id": "h_460", "start": 21.28, "end": 28.81, "sentences": [{"start": 21.28, "end": 28.81, "text": "Dix heures par semaine, sur quarante-six semaines travaillées, cela représente quatre cent soixante heures de capacité potentielle sur une année."}]}, {"id": "h_notca", "start": 28.81, "end": 39.28, "sentences": [{"start": 28.81, "end": 31.62, "text": "Ce n'est pas du chiffre d'affaires supplémentaire promis."}, {"start": 31.734, "end": 39.28, "text": "C'est du temps que le cabinet pourrait consacrer à ses clients, à ses dossiers ou à son développement, si les mesures du pilote confirment l'hypothèse."}]}, {"id": "h_cond", "start": 39.42, "end": 49.361, "sentences": [{"start": 39.42, "end": 40.66, "text": "Mais il y a une condition."}, {"start": 41.02, "end": 49.361, "text": "Dès qu'on touche à des situations patrimoniales, à des documents d'identité ou à des échanges privés, on ne branche pas simplement un chatbot sur tous les fichiers du cabinet."}]}, {"id": "h_mission", "start": 49.361, "end": 55.33, "sentences": [{"start": 49.361, "end": 55.33, "text": "Aujourd'hui, on va suivre une mission, du premier diagnostic jusqu'à la décision de déployer ou d'arrêter."}]}, {"id": "h_plan", "start": 55.33, "end": 63.82, "sentences": [{"start": 55.33, "end": 63.82, "text": "On va noter le fonctionnement du cabinet, voir où passe son temps, puis mettre trois agents au travail, avec un CGP qui garde la main à chaque étape."}]}], "end": 64.587}, {"id": "title", "title": "Titre", "start": 64.587, "beats": [{"id": "t_disc", "start": 65.387, "end": 74.187, "sentences": [{"start": 65.387, "end": 69.947, "text": "Précision avant de commencer : ceci est une simulation pédagogique."}, {"start": 70.147, "end": 74.187, "text": "Le cabinet, les personnes, les dossiers et les chiffres sont fictifs."}]}], "end": 75.037}, {"id": "cabinet", "title": "Le cabinet que l'on audite", "start": 75.037, "beats": [{"id": "c_name", "start": 75.677, "end": 81.757, "sentences": [{"start": 75.677, "end": 78.231, "text": "Notre cabinet fictif s'appelle Horizon Patrimoine."}, {"start": 78.231, "end": 81.757, "text": "Il est installé à Aix-en-Provence et compte trois personnes."}]}, {"id": "c_sophie", "start": 82.037, "end": 89.057, "sentences": [{"start": 82.037, "end": 83.377, "text": "Sophie dirige le cabinet."}, {"start": 83.697, "end": 89.057, "text": "Elle conduit les rendez-vous patrimoniaux, prend les décisions de conseil et valide les communications importantes."}]}, {"id": "c_karim", "start": 89.377, "end": 94.617, "sentences": [{"start": 89.377, "end": 90.677, "text": "Karim est conseiller."}, {"start": 90.897, "end": 94.617, "text": "Il prépare les dossiers, suit une partie des clients et réalise des rendez-vous."}]}, {"id": "c_lea", "start": 94.857, "end": 101.487, "sentences": [{"start": 94.857, "end": 99.677, "text": "Léa coordonne l'accueil, l'agenda, les demandes de pièces et le suivi administratif."}, {"start": 99.837, "end": 101.487, "text": "Elle travaille quatre jours par semaine."}]}, {"id": "c_180", "start": 101.487, "end": 108.757, "sentences": [{"start": 101.487, "end": 108.757, "text": "Dans notre simulation, le cabinet suit environ cent quatre-vingts foyers clients et reçoit régulièrement de nouveaux prospects."}]}, {"id": "c_statut", "start": 109.137, "end": 116.757, "sentences": [{"start": 109.137, "end": 116.757, "text": "On ne suppose aucun statut réglementaire unique : une vraie mission vérifierait les statuts du cabinet, ses prestations et ses procédures."}]}, {"id": "c_tools", "start": 116.851, "end": 128.217, "sentences": [{"start": 116.851, "end": 123.697, "text": "L'équipe utilise un CRM, une messagerie, un agenda, un espace documentaire et des modèles de documents."}, {"start": 123.957, "end": 125.247, "text": "Les outils existent."}, {"start": 125.247, "end": 128.217, "text": "Le problème, ce sont les passages de l'un à l'autre."}]}, {"id": "c_before", "start": 128.557, "end": 139.697, "sentences": [{"start": 128.557, "end": 139.697, "text": "Avant un rendez-vous, Sophie retrouve une note dans le CRM, cherche le dernier échange dans sa messagerie, ouvre les pièces dans un dossier partagé et vérifie si une action promise a été faite."}]}, {"id": "c_after", "start": 139.917, "end": 145.157, "sentences": [{"start": 139.917, "end": 145.157, "text": "Après le rendez-vous, elle refait une partie du chemin pour rédiger le compte rendu et organiser la suite."}]}, {"id": "c_relay", "start": 145.471, "end": 148.129, "sentences": [{"start": 145.471, "end": 148.129, "text": "C'est sur ces passages de relais que porte notre audit."}]}], "end": 148.979}, {"id": "audit", "title": "L'audit, avant de parler d'agents", "start": 148.979, "beats": [{"id": "a_people", "start": 149.579, "end": 153.239, "sentences": [{"start": 149.579, "end": 153.239, "text": "La mission commence avec les personnes, pas avec une démonstration d'IA."}]}, {"id": "a_show", "start": 153.519, "end": 157.499, "sentences": [{"start": 153.519, "end": 157.499, "text": "Pendant le diagnostic, on demande à chacun de montrer un dossier de bout en bout."}]}, {"id": "a_q", "start": 157.939, "end": 165.939, "sentences": [{"start": 157.939, "end": 159.059, "text": "Comment arrive une demande ?"}, {"start": 159.379, "end": 160.839, "text": "Quelles sources sont consultées ?"}, {"start": 161.059, "end": 162.619, "text": "Qui repère une pièce manquante ?"}, {"start": 162.739, "end": 164.219, "text": "Qui valide le compte rendu ?"}, {"start": 164.419, "end": 165.939, "text": "Où voit-on la prochaine action ?"}]}, {"id": "a_cols", "start": 166.259, "end": 172.449, "sentences": [{"start": 166.259, "end": 172.449, "text": "On distingue ce que l'équipe déclare faire, ce qu'on peut observer dans les outils, et ce qu'il faudra mesurer pendant le pilote."}]}, {"id": "a_split", "start": 172.449, "end": 179.499, "sentences": [{"start": 172.449, "end": 179.499, "text": "On répartit ensuite vingt-quatre heures hebdomadaires de travail répétitif en trois blocs, sans compter deux fois la même tâche."}]}, {"id": "a_8", "start": 179.699, "end": 185.139, "sentences": [{"start": 179.699, "end": 185.139, "text": "Huit heures pour préparer les rendez-vous, rassembler le contexte et remettre les notes en forme après l'échange."}]}, {"id": "a_9", "start": 185.579, "end": 190.879, "sentences": [{"start": 185.579, "end": 190.879, "text": "Neuf heures pour rechercher les pièces, vérifier des listes de contrôle et préparer les revues de dossiers."}]}, {"id": "a_7", "start": 191.239, "end": 196.869, "sentences": [{"start": 191.239, "end": 196.869, "text": "Sept heures pour retrouver les engagements, rédiger des brouillons de suivi et préparer les priorités de la semaine."}]}, {"id": "a_sum", "start": 196.869, "end": 208.599, "sentences": [{"start": 196.869, "end": 200.579, "text": "Huit plus neuf plus sept : vingt-quatre heures."}, {"start": 200.719, "end": 202.299, "text": "Ce sont des hypothèses de départ."}, {"start": 202.599, "end": 208.599, "text": "Dans un vrai cabinet, il faudrait chronométrer un échantillon de tâches et tenir compte des différences entre dossiers."}]}, {"id": "a_grid", "start": 208.819, "end": 212.799, "sentences": [{"start": 208.819, "end": 212.799, "text": "On note aussi le fonctionnement du cabinet sur cinq critères, chacun sur vingt."}]}, {"id": "a_s1", "start": 213.159, "end": 218.319, "sentences": [{"start": 213.159, "end": 215.099, "text": "Processus : treize sur vingt."}, {"start": 215.253, "end": 218.319, "text": "L'équipe connaît les étapes, mais elles sont peu documentées."}]}, {"id": "a_s2", "start": 218.759, "end": 224.439, "sentences": [{"start": 218.759, "end": 221.229, "text": "Interconnexion des outils : six sur vingt."}, {"start": 221.229, "end": 224.439, "text": "Plusieurs informations doivent être recherchées et ressaisies."}]}, {"id": "a_s3", "start": 224.559, "end": 230.799, "sentences": [{"start": 224.559, "end": 227.479, "text": "Maîtrise des accès et des données : sept sur vingt."}, {"start": 227.759, "end": 230.799, "text": "Les règles d'usage des outils d'IA restent à préciser."}]}, {"id": "a_s4", "start": 231.119, "end": 237.459, "sentences": [{"start": 231.119, "end": 233.599, "text": "Appropriation par l'équipe : neuf sur vingt."}, {"start": 233.799, "end": 237.459, "text": "Chacun est intéressé, personne n'a encore testé un workflow complet."}]}, {"id": "a_s5", "start": 237.799, "end": 244.939, "sentences": [{"start": 237.799, "end": 240.899, "text": "Validations et traçabilité : dix sur vingt."}, {"start": 241.179, "end": 244.939, "text": "Les décisions humaines existent, mais leur historique est difficile à retrouver."}]}, {"id": "a_45", "start": 245.179, "end": 247.069, "sentences": [{"start": 245.179, "end": 247.069, "text": "Total : quarante-cinq sur cent."}]}, {"id": "a_not", "start": 247.069, "end": 256.559, "sentences": [{"start": 247.069, "end": 253.719, "text": "Ce n'est pas une mesure du professionnalisme des conseillers, mais la photographie fictive d'un système de travail, selon notre grille."}, {"start": 254.019, "end": 256.559, "text": "La mission devra rendre chaque critère vérifiable."}]}, {"id": "a_map", "start": 256.899, "end": 261.539, "sentences": [{"start": 256.899, "end": 261.539, "text": "On range ensuite les tâches observées dans les cinq domaines de la cartographie Agentic Wealth."}]}, {"id": "a_d1", "start": 261.859, "end": 266.359, "sentences": [{"start": 261.859, "end": 266.359, "text": "Acquisition et conversion : prospects, premiers rendez-vous, relances."}]}, {"id": "a_d2", "start": 266.619, "end": 270.949, "sentences": [{"start": 266.619, "end": 270.949, "text": "Conseil et préparation : briefs, comptes rendus, questions à poser."}]}, {"id": "a_d3", "start": 270.949, "end": 276.719, "sentences": [{"start": 270.949, "end": 276.719, "text": "Conformité et traçabilité : pièces, listes de contrôle, journaux de validation."}]}, {"id": "a_d4", "start": 277.319, "end": 281.899, "sentences": [{"start": 277.319, "end": 281.899, "text": "Service et relation client : demandes entrantes, engagements, réponses."}]}, {"id": "a_d5", "start": 282.199, "end": 286.899, "sentences": [{"start": 282.199, "end": 286.899, "text": "Pilotage du cabinet : priorités, échéances, dossiers sans action récente."}]}, {"id": "a_rule", "start": 287.079, "end": 293.639, "sentences": [{"start": 287.079, "end": 290.919, "text": "Partout, la même règle : l'agent prépare, le conseiller décide."}, {"start": 291.159, "end": 293.639, "text": "Voyons trois agents à l'œuvre, sur une semaine type."}]}], "end": 294.489}, {"id": "agent1", "title": "Agent 1 : préparer le rendez-vous et sa suite", "start": 294.489, "beats": [{"id": "p_intro", "start": 295.289, "end": 303.449, "sentences": [{"start": 295.289, "end": 296.129, "text": "Première scène."}, {"start": 296.589, "end": 298.669, "text": "Mardi, huit heures trente-cinq."}, {"start": 298.789, "end": 303.449, "text": "Sophie a un rendez-vous de suivi à quatorze heures avec Camille, une cliente fictive."}]}, {"id": "p_today", "start": 303.749, "end": 315.469, "sentences": [{"start": 303.749, "end": 311.549, "text": "Sans agent, elle ouvre le CRM, cherche le dernier compte rendu, relit trois échanges, vérifie les documents et note ses questions."}, {"start": 311.849, "end": 315.469, "text": "Après le rendez-vous, elle rédige le compte rendu et crée les actions."}]}, {"id": "p_today2", "start": 315.809, "end": 318.989, "sentences": [{"start": 315.809, "end": 318.989, "text": "Cette chaîne pèse lourd dans les huit heures du premier bloc."}]}, {"id": "p_path", "start": 319.209, "end": 323.529, "sentences": [{"start": 319.209, "end": 323.529, "text": "Voici le parcours à tester : onze étapes, dont trois validations humaines."}]}, {"id": "p_1", "start": 323.849, "end": 329.249, "sentences": [{"start": 323.849, "end": 327.169, "text": "Étape un : Sophie sélectionne elle-même le rendez-vous."}, {"start": 327.263, "end": 329.249, "text": "L'agent ne choisit pas seul les dossiers."}]}, {"id": "p_2", "start": 329.509, "end": 340.469, "sentences": [{"start": 329.509, "end": 340.469, "text": "Étape deux : elle autorise les sources utiles pour ce dossier : fiche CRM, comptes rendus validés, échanges professionnels pertinents, documents auxquels elle est habilitée à accéder."}]}, {"id": "p_2b", "start": 340.769, "end": 345.969, "sentences": [{"start": 340.769, "end": 345.969, "text": "Une archive ancienne et la messagerie complète restent grisées : elles sont hors périmètre."}]}, {"id": "p_3", "start": 346.349, "end": 352.019, "sentences": [{"start": 346.349, "end": 348.229, "text": "Étape trois : la collecte."}, {"start": 348.323, "end": 352.019, "text": "L'agent ne lit que ces sources, et garde l'origine de chaque information."}]}, {"id": "p_4", "start": 352.019, "end": 364.129, "sentences": [{"start": 352.019, "end": 354.749, "text": "Étape quatre : le rapprochement."}, {"start": 355.149, "end": 361.469, "text": "La fiche CRM indique une dernière revue le douze mars, le compte rendu validé le quatorze mars."}, {"start": 361.623, "end": 364.129, "text": "L'agent ne choisit pas : il signale l'écart."}]}, {"id": "p_5", "start": 364.469, "end": 375.359, "sentences": [{"start": 364.469, "end": 366.229, "text": "Étape cinq : les manques."}, {"start": 366.349, "end": 373.349, "text": "Un justificatif introuvable, une échéance citée dans un échange mais absente du suivi, une information vieille de deux ans."}, {"start": 373.509, "end": 375.359, "text": "Chaque point est listé avec sa source."}]}, {"id": "p_6", "start": 375.359, "end": 387.269, "sentences": [{"start": 375.359, "end": 377.509, "text": "Étape six : le brief."}, {"start": 378.069, "end": 385.189, "text": "En haut, les faits sourcés : dernier échange, objectifs exprimés par la cliente, actions convenues, documents disponibles."}, {"start": 385.349, "end": 387.269, "text": "Plus bas, les points à vérifier."}]}, {"id": "p_6q", "start": 387.569, "end": 398.309, "sentences": [{"start": 387.569, "end": 395.629, "text": "Puis des questions pour l'entretien, comme : « L'objectif formulé au dernier rendez-vous est-il toujours d'actualité ? » Une question aide la conversation."}, {"start": 396.049, "end": 398.309, "text": "Elle ne conclut rien sur la situation de Camille."}]}, {"id": "p_7", "start": 398.569, "end": 411.709, "sentences": [{"start": 398.569, "end": 400.309, "text": "Étape sept : la correction."}, {"start": 400.809, "end": 402.679, "text": "Sophie voit d'où vient chaque élément."}, {"start": 402.679, "end": 408.289, "text": "Elle retire une question peu pertinente, corrige la date de la dernière revue, puis valide sa version."}, {"start": 408.503, "end": 411.709, "text": "C'est Sophie qui mène le rendez-vous et interprète les réponses."}]}, {"id": "p_8", "start": 411.969, "end": 420.889, "sentences": [{"start": 411.969, "end": 416.303, "text": "Étape huit : le rendez-vous, de quatorze heures à quinze heures dix."}, {"start": 416.429, "end": 420.889, "text": "Pas d'écran d'IA : la conversation appartient à la cliente et à sa conseillère."}]}, {"id": "p_9", "start": 421.229, "end": 430.549, "sentences": [{"start": 421.229, "end": 423.929, "text": "Étape neuf : le brouillon de compte rendu."}, {"start": 424.229, "end": 430.549, "text": "À quinze heures dix, Sophie saisit ses notes, ou une transcription si celle-ci est autorisée et encadrée."}]}, {"id": "p_9b", "start": 430.691, "end": 439.289, "sentences": [{"start": 430.691, "end": 439.289, "text": "L'agent sépare quatre choses : les faits rapportés par la cliente, les questions ouvertes, les décisions réellement prises par Sophie, et les actions proposées."}]}, {"id": "p_9c", "start": 439.589, "end": 448.429, "sentences": [{"start": 439.589, "end": 443.389, "text": "Il signale une phrase ambiguë : « revoir le dossier le mois prochain »."}, {"start": 443.655, "end": 446.169, "text": "Revoir quoi, avec qui, à quelle date ?"}, {"start": 446.529, "end": 448.429, "text": "Il ne complète pas la promesse de lui-même."}]}, {"id": "p_10", "start": 448.749, "end": 457.809, "sentences": [{"start": 448.749, "end": 450.569, "text": "Étape dix : la validation."}, {"start": 450.989, "end": 455.679, "text": "Sophie précise : un point téléphonique dans quatre semaines, qu'elle mènera elle-même."}, {"start": 455.679, "end": 457.809, "text": "Puis elle valide le compte rendu."}]}, {"id": "p_11", "start": 458.169, "end": 469.169, "sentences": [{"start": 458.169, "end": 460.829, "text": "Étape onze : les tâches et le suivi."}, {"start": 461.023, "end": 465.169, "text": "L'agent propose deux tâches, avec responsable et échéance à confirmer."}, {"start": 465.409, "end": 469.169, "text": "Une fois validées par Sophie, elles rejoignent l'outil de suivi autorisé."}]}, {"id": "p_11b", "start": 469.409, "end": 476.749, "sentences": [{"start": 469.409, "end": 471.369, "text": "Un message à Camille reste un brouillon."}, {"start": 471.609, "end": 475.109, "text": "Sophie contrôle le destinataire, le contenu et l'envoi."}, {"start": 475.369, "end": 476.749, "text": "Rien ne part sans son clic."}]}, {"id": "p_gain", "start": 477.089, "end": 483.379, "sentences": [{"start": 477.089, "end": 480.969, "text": "Sur les huit heures de ce bloc, l'objectif de test est d'en récupérer quatre."}, {"start": 481.263, "end": 483.379, "text": "C'est un gain cible, pas un résultat."}]}, {"id": "p_measure", "start": 483.379, "end": 490.021, "sentences": [{"start": 483.379, "end": 490.021, "text": "On mesurera le temps avant et après, les corrections, les erreurs, et l'utilité réelle des briefs."}]}, {"id": "p_jalon", "start": 490.229, "end": 498.469, "sentences": [{"start": 490.229, "end": 495.269, "text": "Premier jalon, volontairement petit : trois briefs, puis une décision de Sophie."}, {"start": 495.609, "end": 498.469, "text": "Continuer, ajuster, ou retirer l'accès."}]}], "end": 499.296}, {"id": "agent2", "title": "Agent 2 : voir les manques, sans déclarer un dossier conforme", "start": 499.296, "beats": [{"id": "d_intro", "start": 500.096, "end": 506.916, "sentences": [{"start": 500.096, "end": 500.936, "text": "Deuxième scène."}, {"start": 501.276, "end": 503.076, "text": "Mercredi, dix heures vingt."}, {"start": 503.436, "end": 506.916, "text": "Léa prépare plusieurs dossiers pour des rendez-vous et une revue périodique."}]}, {"id": "d_today", "start": 507.096, "end": 514.956, "sentences": [{"start": 507.096, "end": 514.956, "text": "Elle parcourt les répertoires, compare les fichiers aux listes du cabinet, cherche des dates, et fait trancher les cas incertains par Sophie ou Karim."}]}, {"id": "d_9", "start": 515.256, "end": 518.816, "sentences": [{"start": 515.256, "end": 518.816, "text": "Dans notre simulation, ce travail représente neuf heures par semaine."}]}, {"id": "d_limit", "start": 519.216, "end": 526.696, "sentences": [{"start": 519.216, "end": 522.536, "text": "Première limite : l'agent n'invente pas les règles de contrôle."}, {"start": 522.916, "end": 526.696, "text": "La liste applicable vient du cabinet, validée par la personne compétente."}]}, {"id": "d_frame", "start": 527.076, "end": 535.876, "sentences": [{"start": 527.076, "end": 535.876, "text": "On vérifie aussi le cadre d'accès aux données : quelles sources, quelles personnes habilitées, quelle finalité, quel sous-traitant éventuel, quelle conservation."}]}, {"id": "d_run", "start": 536.356, "end": 547.936, "sentences": [{"start": 536.356, "end": 547.936, "text": "Pour un dossier sélectionné, l'agent lit la liste approuvée, inventorie seulement les documents autorisés, et range chaque ligne en quatre colonnes : présent, absent, ambigu, ou non vérifié."}]}, {"id": "d_amb", "start": 548.116, "end": 559.896, "sentences": [{"start": 548.116, "end": 551.776, "text": "Supposons un justificatif présent, mais dont la date est illisible."}, {"start": 551.97, "end": 555.056, "text": "L'agent ne le marque ni « valide », ni « périmé »."}, {"start": 555.416, "end": 559.896, "text": "Il le classe en ambigu, et montre le document source avec la raison du signalement."}]}, {"id": "d_lea", "start": 560.276, "end": 563.956, "sentences": [{"start": 560.276, "end": 563.956, "text": "Léa retrouve une meilleure version, ou demande à Sophie quelle suite donner."}]}, {"id": "d_review", "start": 564.296, "end": 571.656, "sentences": [{"start": 564.296, "end": 571.656, "text": "Pour une revue périodique, il compare avec la dernière revue : éléments nouveaux, inchangés, pièces à examiner, contrôles sans réponse."}]}, {"id": "d_human", "start": 571.956, "end": 580.456, "sentences": [{"start": 571.956, "end": 576.596, "text": "Si une information essentielle manque, l'écran indique : décision humaine requise."}, {"start": 576.656, "end": 580.456, "text": "Jamais de badge « dossier conforme » sur la seule base de sa lecture."}]}, {"id": "d_kyc", "start": 580.83, "end": 588.916, "sentences": [{"start": 580.83, "end": 583.896, "text": "C'est essentiel pour la connaissance client et la vigilance."}, {"start": 584.076, "end": 588.916, "text": "Selon les activités exercées, le professionnel applique les exigences qui lui sont propres."}]}, {"id": "d_amf", "start": 589.096, "end": 606.516, "sentences": [{"start": 589.096, "end": 600.856, "text": "Pour le conseil en investissements financiers, l'AMF décrit notamment les informations à recueillir avant de conseiller, et la déclaration d'adéquation remise au client avant la réalisation de l'opération conseillée."}, {"start": 601.016, "end": 606.516, "text": "Pour les professionnels assujettis, les obligations de vigilance suivent une approche fondée sur les risques."}]}, {"id": "d_nostat", "start": 606.71, "end": 615.116, "sentences": [{"start": 606.71, "end": 611.236, "text": "L'agent aide à préparer et à retrouver des éléments, sans statuer sur leur suffisance."}, {"start": 611.656, "end": 615.116, "text": "Et cette vidéo n'est pas un modèle universel de dossier réglementaire."}]}, {"id": "d_log", "start": 615.396, "end": 625.616, "sentences": [{"start": 615.396, "end": 625.616, "text": "Après la revue, un journal conserve les sources consultées, la version du résultat, la correction de Léa, la validation de Sophie et l'horodatage, selon les règles de conservation du cabinet."}]}, {"id": "d_lognot", "start": 626.036, "end": 631.546, "sentences": [{"start": 626.036, "end": 631.546, "text": "Mais un journal technique n'est pas, à lui seul, la preuve que les obligations réglementaires sont remplies."}]}, {"id": "d_gain", "start": 631.546, "end": 637.156, "sentences": [{"start": 631.546, "end": 637.156, "text": "Hypothèse : ramener ce bloc de neuf à six heures par semaine, soit trois heures récupérées."}]}, {"id": "d_measure", "start": 637.396, "end": 643.836, "sentences": [{"start": 637.396, "end": 643.836, "text": "Le pilote suivra aussi les faux positifs, les vrais manques détectés, et les situations correctement laissées à l'équipe."}]}], "end": 644.613}, {"id": "agent3", "title": "Agent 3 : relation client et pilotage de la semaine", "start": 644.613, "beats": [{"id": "s_intro", "start": 645.413, "end": 652.813, "sentences": [{"start": 645.413, "end": 646.273, "text": "Troisième scène."}, {"start": 646.613, "end": 648.575, "text": "Jeudi, seize heures quarante."}, {"start": 648.833, "end": 652.813, "text": "Une cliente écrit : « Pouvez-vous me rappeler ce que nous avions convenu pour la suite ? »"}]}, {"id": "s_today", "start": 653.213, "end": 662.673, "sentences": [{"start": 653.213, "end": 658.413, "text": "Léa cherche le dernier compte rendu, vérifie la tâche, puis demande à Karim si l'action est faite."}, {"start": 658.653, "end": 662.673, "text": "En parallèle, un prospect attend un retour et deux échéances approchent."}]}, {"id": "s_class", "start": 662.787, "end": 670.973, "sentences": [{"start": 662.787, "end": 670.973, "text": "L'agent de service classe la demande, puis rassemble les seuls éléments autorisés : le message, le compte rendu validé, la tâche et son statut."}]}, {"id": "s_card", "start": 671.253, "end": 678.713, "sentences": [{"start": 671.253, "end": 672.373, "text": "Il prépare une fiche."}, {"start": 672.573, "end": 673.953, "text": "Voici l'engagement retrouvé."}, {"start": 674.093, "end": 674.863, "text": "Voici sa source."}, {"start": 674.863, "end": 676.393, "text": "Voici l'état connu."}, {"start": 676.573, "end": 678.713, "text": "Et voici ce que nous ne savons pas encore."}]}, {"id": "s_draft", "start": 678.973, "end": 686.393, "sentences": [{"start": 678.973, "end": 680.953, "text": "Il peut rédiger un brouillon de réponse."}, {"start": 681.313, "end": 686.393, "text": "Ici, la tâche n'a pas de statut fiable : le brouillon n'affirme donc pas qu'elle est terminée."}]}, {"id": "s_karim", "start": 686.733, "end": 695.651, "sentences": [{"start": 686.733, "end": 690.013, "text": "Karim vérifie, complète, puis décide de l'envoi."}, {"start": 690.193, "end": 693.513, "text": "Seul Karim dispose du bouton « vérifier et envoyer »."}, {"start": 693.807, "end": 695.651, "text": "L'agent n'a qu'un bouton : « préparer »."}]}, {"id": "s_prosp", "start": 696.253, "end": 706.113, "sentences": [{"start": 696.253, "end": 697.533, "text": "Même logique pour un prospect."}, {"start": 697.847, "end": 706.113, "text": "L'agent propose une fiche de qualification à partir du formulaire et des échanges autorisés, des questions pour un premier rendez-vous, et une relance contextualisée."}]}, {"id": "s_noscore", "start": 706.373, "end": 714.533, "sentences": [{"start": 706.373, "end": 711.573, "text": "Le conseiller choisit de prendre contact, d'accepter ou non le prospect, et d'envoyer chaque message."}, {"start": 711.853, "end": 714.533, "text": "Aucun score automatique de « valeur » de la personne."}]}, {"id": "s_monday", "start": 714.933, "end": 718.533, "sentences": [{"start": 714.933, "end": 718.533, "text": "Le lundi suivant, à neuf heures, Sophie ouvre une vue de pilotage."}]}, {"id": "s_lists", "start": 718.647, "end": 731.503, "sentences": [{"start": 718.647, "end": 731.503, "text": "L'agent a rapproché agenda, tâches et statuts du CRM en quatre listes : rendez-vous à préparer, engagements sans responsable confirmé, échéances à vérifier, et dossiers sans action récente, selon une règle choisie par le cabinet."}]}, {"id": "s_reason", "start": 731.503, "end": 737.909, "sentences": [{"start": 731.503, "end": 733.853, "text": "Chaque signal comporte une raison."}, {"start": 734.033, "end": 737.909, "text": "Un dossier sans activité récente n'est pas étiqueté « client négligé »."}]}, {"id": "s_arb", "start": 738.333, "end": 747.873, "sentences": [{"start": 738.333, "end": 746.6, "text": "Sophie répond : « celui-ci attend volontairement une date », « celui-là mérite un appel », « cette donnée du CRM est incorrecte »."}, {"start": 746.6, "end": 747.873, "text": "C'est elle qui arbitre."}]}, {"id": "s_gain", "start": 748.153, "end": 754.013, "sentences": [{"start": 748.153, "end": 754.013, "text": "Notre hypothèse : ramener ce bloc de sept à quatre heures par semaine, soit trois heures récupérées."}]}, {"id": "s_measure", "start": 754.233, "end": 766.173, "sentences": [{"start": 754.233, "end": 759.883, "text": "On compte aussi les alertes utiles ou écartées, les brouillons corrigés et les engagements retrouvés."}, {"start": 759.883, "end": 766.173, "text": "Si le tableau produit du bruit, on réduit son périmètre : un cockpit que personne n'ouvre n'est pas un gain."}]}], "end": 767.023}, {"id": "data", "title": "La question des données et des limites", "start": 767.023, "beats": [{"id": "x_q", "start": 767.823, "end": 773.763, "sentences": [{"start": 767.823, "end": 773.763, "text": "Sophie pose alors la bonne question : « Pour préparer tout ça, l'agent doit-il lire tous mes mails et tous mes dossiers ? »"}]}, {"id": "x_no", "start": 774.203, "end": 775.863, "sentences": [{"start": 774.203, "end": 775.863, "text": "La réponse de la mission est non."}]}, {"id": "x_flow", "start": 776.123, "end": 788.763, "sentences": [{"start": 776.123, "end": 782.753, "text": "Chaque workflow a un objectif défini, des sources approuvées, des droits limités et des personnes habilitées."}, {"start": 782.753, "end": 788.763, "text": "Source autorisée, accès limité, préparation, validation humaine, destination autorisée."}]}, {"id": "x_check", "start": 789.023, "end": 799.003, "sentences": [{"start": 789.023, "end": 799.003, "text": "Avant d'utiliser des données clients, le cabinet examine ses responsabilités, ses contrats avec les prestataires, la sécurité, la conservation et les éventuels transferts."}]}, {"id": "x_host", "start": 799.003, "end": 813.303, "sentences": [{"start": 799.003, "end": 805.043, "text": "Héberger un modèle soi-même, ou choisir un modèle open source, ne suffit pas à rendre un traitement conforme."}, {"start": 805.143, "end": 813.303, "text": "La CNIL rappelle notamment l'importance d'encadrer la sous-traitance, de protéger les données et de garder une intervention humaine adaptée."}]}, {"id": "x_stop", "start": 813.603, "end": 815.843, "sentences": [{"start": 813.603, "end": 815.843, "text": "Concrètement, l'agent sait s'arrêter."}]}, {"id": "x_s1", "start": 816.157, "end": 820.703, "sentences": [{"start": 816.157, "end": 820.703, "text": "S'il ne retrouve pas la source d'un fait, il écrit : information non vérifiée."}]}, {"id": "x_s2", "start": 820.903, "end": 824.143, "sentences": [{"start": 820.903, "end": 824.143, "text": "Si une pièce est illisible, il demande une vérification."}]}, {"id": "x_s3", "start": 824.603, "end": 831.283, "sentences": [{"start": 824.603, "end": 831.283, "text": "Si une demande implique une interprétation patrimoniale ou une décision de conseil, il la transmet au CGP."}]}, {"id": "x_never", "start": 831.483, "end": 843.043, "sentences": [{"start": 831.483, "end": 833.123, "text": "Il ne recommande aucun produit."}, {"start": 833.323, "end": 835.703, "text": "Il ne détermine pas seul un profil de risque."}, {"start": 835.903, "end": 838.003, "text": "Il ne déclare pas un dossier conforme."}, {"start": 838.043, "end": 840.203, "text": "Il ne contacte personne automatiquement."}, {"start": 840.363, "end": 843.043, "text": "Il ne modifie pas un engagement client sans validation."}]}, {"id": "x_demo", "start": 843.297, "end": 853.163, "sentences": [{"start": 843.297, "end": 848.283, "text": "C'est pourquoi un vrai déploiement commence avec des données de démonstration et un accès limité."}, {"start": 848.403, "end": 853.163, "text": "Les données réelles arrivent seulement après revue du cadre applicable et autorisation du cabinet."}]}], "end": 854.013}, {"id": "bilan", "title": "Le bilan chiffré", "start": 854.013, "beats": [{"id": "b_intro", "start": 854.813, "end": 858.273, "sentences": [{"start": 854.813, "end": 858.273, "text": "Reprenons nos chiffres, sans additionner des promesses incompatibles."}]}, {"id": "b_1", "start": 858.453, "end": 864.673, "sentences": [{"start": 858.453, "end": 862.993, "text": "Préparation des rendez-vous et suivi : huit heures avant, quatre visées après."}, {"start": 863.273, "end": 864.673, "text": "Quatre heures à confirmer."}]}, {"id": "b_2", "start": 864.853, "end": 869.653, "sentences": [{"start": 864.853, "end": 868.053, "text": "Contrôles et revues : neuf heures avant, six visées."}, {"start": 868.233, "end": 869.653, "text": "Trois heures à confirmer."}]}, {"id": "b_3", "start": 869.953, "end": 875.853, "sentences": [{"start": 869.953, "end": 874.033, "text": "Relation client et pilotage : sept heures avant, quatre visées."}, {"start": 874.393, "end": 875.853, "text": "Trois heures à confirmer."}]}, {"id": "b_sum", "start": 876.153, "end": 888.933, "sentences": [{"start": 876.153, "end": 880.523, "text": "Avant : huit plus neuf plus sept, vingt-quatre heures."}, {"start": 880.523, "end": 886.213, "text": "Après, visé : quatre plus six plus quatre, quatorze heures."}, {"start": 886.527, "end": 888.933, "text": "L'écart visé : dix heures par semaine."}]}, {"id": "b_cap", "start": 889.313, "end": 896.353, "sentences": [{"start": 889.313, "end": 893.913, "text": "Dix heures de capacité potentielle, à condition que les gains résistent à l'observation."}, {"start": 894.333, "end": 896.353, "text": "La mesure réelle reste à établir."}]}, {"id": "b_460", "start": 896.793, "end": 902.573, "sentences": [{"start": 896.793, "end": 902.573, "text": "Sur une année, dix heures multipliées par quarante-six semaines travaillées donnent quatre cent soixante heures."}]}, {"id": "b_euro", "start": 902.893, "end": 912.173, "sentences": [{"start": 902.893, "end": 912.173, "text": "À titre d'illustration seulement, avec une heure interne valorisée à soixante euros, cela représenterait vingt-sept mille six cents euros de capacité théorique annuelle."}]}, {"id": "b_not", "start": 912.493, "end": 922.613, "sentences": [{"start": 912.493, "end": 917.173, "text": "Ce n'est ni une économie de trésorerie acquise, ni un revenu additionnel."}, {"start": 917.393, "end": 922.613, "text": "Capacité théorique, économies encaissées et chiffre d'affaires sont trois choses différentes."}]}, {"id": "b_minus", "start": 922.993, "end": 929.013, "sentences": [{"start": 922.993, "end": 929.013, "text": "Il faut encore déduire le temps de contrôle humain, le coût des outils, la maintenance et les erreurs à corriger."}]}], "end": 929.863}, {"id": "deploy", "title": "Déploiement et conclusion", "start": 929.863, "beats": [{"id": "y_first", "start": 930.663, "end": 940.043, "sentences": [{"start": 930.663, "end": 932.123, "text": "Quel agent déployer en premier ?"}, {"start": 932.463, "end": 940.043, "text": "Ici, je commencerais par la préparation d'un rendez-vous, sur trois briefs : un périmètre étroit, compréhensible par Sophie, et mesurable."}]}, {"id": "y_order", "start": 940.363, "end": 949.263, "sentences": [{"start": 940.363, "end": 949.263, "text": "Si les briefs sont utiles et les accès maîtrisés, on ajoute le compte rendu et les tâches, puis les contrôles documentaires, et enfin la relation client et le cockpit."}]}, {"id": "y_plan", "start": 949.723, "end": 951.303, "sentences": [{"start": 949.723, "end": 951.303, "text": "Voici le planning proposé."}]}, {"id": "y_w12", "start": 951.603, "end": 958.413, "sentences": [{"start": 951.603, "end": 958.413, "text": "Semaines un et deux : diagnostic réel, chronométrage, cartographie des données, et choix d'un seul cas d'usage."}]}, {"id": "y_w35", "start": 958.413, "end": 969.443, "sentences": [{"start": 958.413, "end": 966.683, "text": "Semaines trois à cinq : construction et test du premier workflow, d'abord sur des données fictives, puis sur un périmètre autorisé."}, {"start": 966.883, "end": 969.443, "text": "Trois briefs, relus intégralement par Sophie."}]}, {"id": "y_w68", "start": 969.763, "end": 980.043, "sentences": [{"start": 969.763, "end": 974.283, "text": "Semaines six à huit : décision d'étendre, d'ajuster ou d'arrêter."}, {"start": 974.663, "end": 980.043, "text": "Les autres agents n'entrent dans le pilote que si le premier a fait ses preuves et si leurs accès sont approuvés."}]}, {"id": "y_not3", "start": 980.363, "end": 984.193, "sentences": [{"start": 980.363, "end": 984.193, "text": "Huit semaines ne promettent donc pas trois agents achevés dans tous les cabinets."}]}, {"id": "y_goal", "start": 984.193, "end": 996.023, "sentences": [{"start": 984.193, "end": 989.663, "text": "Le résultat recherché n'est pas un cabinet où l'intelligence artificielle parle à la place du conseiller."}, {"start": 989.737, "end": 996.023, "text": "C'est un cabinet où le conseiller retrouve le contexte, voit les manques, et décide avec moins de recherches dispersées."}]}, {"id": "y_cta", "start": 996.263, "end": 1002.923, "sentences": [{"start": 996.263, "end": 1002.923, "text": "Si vous dirigez un cabinet de gestion de patrimoine, le point de départ est simple : montrez-nous un dossier et une semaine réelle."}]}, {"id": "y_cta2", "start": 1003.183, "end": 1009.723, "sentences": [{"start": 1003.183, "end": 1009.723, "text": "On identifiera ce qui mérite d'être préparé, ce qui doit rester humain, et ce qu'un pilote permettrait réellement de mesurer."}]}, {"id": "y_end", "start": 1009.723, "end": 1015.223, "sentences": [{"start": 1009.723, "end": 1011.377, "text": "Agentic Wealth."}, {"start": 1011.377, "end": 1012.403, "text": "L'agent prépare."}, {"start": 1012.643, "end": 1015.223, "text": "Le CGP valide et décide."}]}], "end": 1018.416}], "cues": [{"start": 1.2, "end": 4.04, "lines": ["Prenons un cabinet de gestion", "de patrimoine fictif."]}, {"start": 4.08, "end": 8.119, "lines": ["Il passe environ vingt-quatre heures", "par semaine à rechercher des informations,"]}, {"start": 8.119, "end": 12.51, "lines": ["préparer des rendez-vous, vérifier des", "pièces et reconstruire ses suivis clients."]}, {"start": 12.6, "end": 16.733, "lines": ["Sur ces vingt-quatre heures, notre", "hypothèse est qu'il pourrait en récupérer"]}, {"start": 16.733, "end": 21.17, "lines": ["dix, sans laisser une intelligence", "artificielle conseiller à la place du CGP."]}, {"start": 21.28, "end": 24.784, "lines": ["Dix heures par semaine, sur quarante-six", "semaines travaillées, cela"]}, {"start": 24.784, "end": 28.81, "lines": ["représente quatre cent soixante heures", "de capacité potentielle sur une année."]}, {"start": 28.81, "end": 31.694, "lines": ["Ce n'est pas du chiffre", "d'affaires supplémentaire promis."]}, {"start": 31.734, "end": 35.658, "lines": ["C'est du temps que le cabinet pourrait", "consacrer à ses clients, à ses dossiers"]}, {"start": 35.658, "end": 39.38, "lines": ["ou à son développement, si les mesures", "du pilote confirment l'hypothèse."]}, {"start": 39.42, "end": 40.91, "lines": ["Mais il y a une condition."]}, {"start": 41.02, "end": 43.334, "lines": ["Dès qu'on touche", "à des situations patrimoniales,"]}, {"start": 43.334, "end": 45.841, "lines": ["à des documents d'identité", "ou à des échanges privés,"]}, {"start": 45.841, "end": 49.361, "lines": ["on ne branche pas simplement un chatbot", "sur tous les fichiers du cabinet."]}, {"start": 49.361, "end": 51.521, "lines": ["Aujourd'hui,", "on va suivre une mission,"]}, {"start": 51.521, "end": 55.33, "lines": ["du premier diagnostic jusqu'à", "la décision de déployer ou d'arrêter."]}, {"start": 55.33, "end": 60.149, "lines": ["On va noter le fonctionnement du cabinet,", "voir où passe son temps, puis mettre trois"]}, {"start": 60.149, "end": 64.07, "lines": ["agents au travail, avec un CGP", "qui garde la main à chaque étape."]}, {"start": 65.387, "end": 70.107, "lines": ["Précision avant de commencer :", "ceci est une simulation pédagogique."]}, {"start": 70.147, "end": 74.437, "lines": ["Le cabinet, les personnes,", "les dossiers et les chiffres sont fictifs."]}, {"start": 75.677, "end": 78.231, "lines": ["Notre cabinet fictif", "s'appelle Horizon Patrimoine."]}, {"start": 78.231, "end": 81.997, "lines": ["Il est installé à Aix-en-Provence", "et compte trois personnes."]}, {"start": 82.037, "end": 83.627, "lines": ["Sophie dirige le cabinet."]}, {"start": 83.697, "end": 85.671, "lines": ["Elle conduit les rendez-vous", "patrimoniaux,"]}, {"start": 85.671, "end": 89.307, "lines": ["prend les décisions de conseil et valide", "les communications importantes."]}, {"start": 89.377, "end": 90.857, "lines": ["Karim est conseiller."]}, {"start": 90.897, "end": 94.817, "lines": ["Il prépare les dossiers, suit une partie", "des clients et réalise des rendez-vous."]}, {"start": 94.857, "end": 96.831, "lines": ["Léa coordonne l'accueil, l'agenda,"]}, {"start": 96.831, "end": 99.797, "lines": ["les demandes de pièces", "et le suivi administratif."]}, {"start": 99.837, "end": 101.487, "lines": ["Elle travaille quatre", "jours par semaine."]}, {"start": 101.487, "end": 104.429, "lines": ["Dans notre simulation,", "le cabinet suit environ cent"]}, {"start": 104.429, "end": 109.007, "lines": ["quatre-vingts foyers clients et reçoit", "régulièrement de nouveaux prospects."]}, {"start": 109.137, "end": 113.531, "lines": ["On ne suppose aucun statut réglementaire", "unique : une vraie mission vérifierait"]}, {"start": 113.531, "end": 116.811, "lines": ["les statuts du cabinet,", "ses prestations et ses procédures."]}, {"start": 116.851, "end": 120.274, "lines": ["L'équipe utilise un CRM,", "une messagerie, un agenda,"]}, {"start": 120.274, "end": 123.917, "lines": ["un espace documentaire", "et des modèles de documents."]}, {"start": 123.957, "end": 125.247, "lines": ["Les outils existent."]}, {"start": 125.247, "end": 128.467, "lines": ["Le problème,", "ce sont les passages de l'un à l'autre."]}, {"start": 128.557, "end": 131.998, "lines": ["Avant un rendez-vous, Sophie", "retrouve une note dans le CRM,"]}, {"start": 131.998, "end": 135.672, "lines": ["cherche le dernier échange", "dans sa messagerie, ouvre les pièces"]}, {"start": 135.672, "end": 139.877, "lines": ["dans un dossier partagé et vérifie", "si une action promise a été faite."]}, {"start": 139.917, "end": 142.113, "lines": ["Après le rendez-vous,", "elle refait une partie"]}, {"start": 142.113, "end": 145.407, "lines": ["du chemin pour rédiger le compte", "rendu et organiser la suite."]}, {"start": 145.471, "end": 148.379, "lines": ["C'est sur ces passages", "de relais que porte notre audit."]}, {"start": 149.579, "end": 153.479, "lines": ["La mission commence avec les personnes,", "pas avec une démonstration d'IA."]}, {"start": 153.519, "end": 157.749, "lines": ["Pendant le diagnostic, on demande à chacun", "de montrer un dossier de bout en bout."]}, {"start": 157.939, "end": 159.309, "lines": ["Comment arrive une demande ?"]}, {"start": 159.379, "end": 161.019, "lines": ["Quelles sources sont consultées ?"]}, {"start": 161.059, "end": 162.699, "lines": ["Qui repère une pièce manquante ?"]}, {"start": 162.739, "end": 164.379, "lines": ["Qui valide le compte rendu ?"]}, {"start": 164.419, "end": 166.189, "lines": ["Où voit-on la prochaine action ?"]}, {"start": 166.259, "end": 168.338, "lines": ["On distingue ce que l'équipe", "déclare faire,"]}, {"start": 168.338, "end": 172.449, "lines": ["ce qu'on peut observer dans les outils, et", "ce qu'il faudra mesurer pendant le pilote."]}, {"start": 172.449, "end": 175.391, "lines": ["On répartit ensuite vingt-quatre", "heures hebdomadaires"]}, {"start": 175.391, "end": 179.659, "lines": ["de travail répétitif en trois blocs,", "sans compter deux fois la même tâche."]}, {"start": 179.699, "end": 181.739, "lines": ["Huit heures pour préparer", "les rendez-vous,"]}, {"start": 181.739, "end": 185.389, "lines": ["rassembler le contexte et remettre", "les notes en forme après l'échange."]}, {"start": 185.579, "end": 187.529, "lines": ["Neuf heures", "pour rechercher les pièces,"]}, {"start": 187.529, "end": 191.129, "lines": ["vérifier des listes de contrôle", "et préparer les revues de dossiers."]}, {"start": 191.239, "end": 193.344, "lines": ["Sept heures pour retrouver", "les engagements,"]}, {"start": 193.344, "end": 196.869, "lines": ["rédiger des brouillons de suivi", "et préparer les priorités de la semaine."]}, {"start": 196.869, "end": 200.679, "lines": ["Huit plus neuf plus sept :", "vingt-quatre heures."]}, {"start": 200.719, "end": 202.549, "lines": ["Ce sont des hypothèses de départ."]}, {"start": 202.599, "end": 204.938, "lines": ["Dans un vrai cabinet,", "il faudrait chronométrer"]}, {"start": 204.938, "end": 208.779, "lines": ["un échantillon de tâches et tenir", "compte des différences entre dossiers."]}, {"start": 208.819, "end": 213.049, "lines": ["On note aussi le fonctionnement du cabinet", "sur cinq critères, chacun sur vingt."]}, {"start": 213.159, "end": 215.213, "lines": ["Processus : treize sur vingt."]}, {"start": 215.253, "end": 218.569, "lines": ["L'équipe connaît les étapes,", "mais elles sont peu documentées."]}, {"start": 218.759, "end": 221.229, "lines": ["Interconnexion des outils :", "six sur vingt."]}, {"start": 221.229, "end": 224.519, "lines": ["Plusieurs informations doivent", "être recherchées et ressaisies."]}, {"start": 224.559, "end": 227.719, "lines": ["Maîtrise des accès et des données :", "sept sur vingt."]}, {"start": 227.759, "end": 231.049, "lines": ["Les règles d'usage des outils", "d'IA restent à préciser."]}, {"start": 231.119, "end": 233.759, "lines": ["Appropriation par l'équipe :", "neuf sur vingt."]}, {"start": 233.799, "end": 237.709, "lines": ["Chacun est intéressé, personne n'a", "encore testé un workflow complet."]}, {"start": 237.799, "end": 241.139, "lines": ["Validations et traçabilité :", "dix sur vingt."]}, {"start": 241.179, "end": 245.139, "lines": ["Les décisions humaines existent, mais", "leur historique est difficile à retrouver."]}, {"start": 245.179, "end": 247.069, "lines": ["Total : quarante-cinq sur cent."]}, {"start": 247.069, "end": 250.096, "lines": ["Ce n'est pas une mesure", "du professionnalisme des conseillers,"]}, {"start": 250.096, "end": 253.969, "lines": ["mais la photographie fictive d'un", "système de travail, selon notre grille."]}, {"start": 254.019, "end": 256.809, "lines": ["La mission devra rendre", "chaque critère vérifiable."]}, {"start": 256.899, "end": 258.231, "lines": ["On range ensuite les tâches"]}, {"start": 258.231, "end": 261.789, "lines": ["observées dans les cinq domaines", "de la cartographie Agentic Wealth."]}, {"start": 261.859, "end": 266.579, "lines": ["Acquisition et conversion : prospects,", "premiers rendez-vous, relances."]}, {"start": 266.619, "end": 270.949, "lines": ["Conseil et préparation : briefs,", "comptes rendus, questions à poser."]}, {"start": 270.949, "end": 276.969, "lines": ["Conformité et traçabilité : pièces, listes", "de contrôle, journaux de validation."]}, {"start": 277.319, "end": 282.149, "lines": ["Service et relation client :", "demandes entrantes, engagements, réponses."]}, {"start": 282.199, "end": 287.039, "lines": ["Pilotage du cabinet : priorités,", "échéances, dossiers sans action récente."]}, {"start": 287.079, "end": 291.119, "lines": ["Partout, la même règle :", "l'agent prépare, le conseiller décide."]}, {"start": 291.159, "end": 293.889, "lines": ["Voyons trois agents à l'œuvre,", "sur une semaine type."]}, {"start": 295.289, "end": 296.379, "lines": ["Première scène."]}, {"start": 296.589, "end": 298.749, "lines": ["Mardi, huit heures trente-cinq."]}, {"start": 298.789, "end": 302.339, "lines": ["Sophie a un rendez-vous de suivi", "à quatorze heures avec Camille,"]}, {"start": 302.339, "end": 303.699, "lines": ["une cliente fictive."]}, {"start": 303.749, "end": 307.558, "lines": ["Sans agent, elle ouvre le CRM,", "cherche le dernier compte rendu,"]}, {"start": 307.558, "end": 311.799, "lines": ["relit trois échanges, vérifie", "les documents et note ses questions."]}, {"start": 311.849, "end": 315.719, "lines": ["Après le rendez-vous, elle rédige", "le compte rendu et crée les actions."]}, {"start": 315.809, "end": 319.169, "lines": ["Cette chaîne pèse lourd", "dans les huit heures du premier bloc."]}, {"start": 319.209, "end": 323.779, "lines": ["Voici le parcours à tester : onze étapes,", "dont trois validations humaines."]}, {"start": 323.849, "end": 327.223, "lines": ["Étape un : Sophie sélectionne", "elle-même le rendez-vous."]}, {"start": 327.263, "end": 329.469, "lines": ["L'agent ne choisit", "pas seul les dossiers."]}, {"start": 329.509, "end": 333.324, "lines": ["Étape deux : elle autorise", "les sources utiles pour ce dossier :"]}, {"start": 333.324, "end": 337.562, "lines": ["fiche CRM, comptes rendus validés,", "échanges professionnels pertinents,"]}, {"start": 337.562, "end": 340.719, "lines": ["documents auxquels elle", "est habilitée à accéder."]}, {"start": 340.769, "end": 344.467, "lines": ["Une archive ancienne et la messagerie", "complète restent grisées :"]}, {"start": 344.467, "end": 346.219, "lines": ["elles sont hors périmètre."]}, {"start": 346.349, "end": 348.283, "lines": ["Étape trois : la collecte."]}, {"start": 348.323, "end": 352.019, "lines": ["L'agent ne lit que ces sources,", "et garde l'origine de chaque information."]}, {"start": 352.019, "end": 354.999, "lines": ["Étape quatre : le rapprochement."]}, {"start": 355.149, "end": 358.779, "lines": ["La fiche CRM indique", "une dernière revue le douze mars,"]}, {"start": 358.779, "end": 361.583, "lines": ["le compte rendu validé", "le quatorze mars."]}, {"start": 361.623, "end": 364.379, "lines": ["L'agent ne choisit pas :", "il signale l'écart."]}, {"start": 364.469, "end": 366.309, "lines": ["Étape cinq : les manques."]}, {"start": 366.349, "end": 369.045, "lines": ["Un justificatif introuvable,", "une échéance citée"]}, {"start": 369.045, "end": 373.469, "lines": ["dans un échange mais absente du suivi,", "une information vieille de deux ans."]}, {"start": 373.509, "end": 375.359, "lines": ["Chaque point est listé", "avec sa source."]}, {"start": 375.359, "end": 377.759, "lines": ["Étape six : le brief."]}, {"start": 378.069, "end": 380.717, "lines": ["En haut, les faits sourcés :", "dernier échange,"]}, {"start": 380.717, "end": 385.309, "lines": ["objectifs exprimés par la cliente,", "actions convenues, documents disponibles."]}, {"start": 385.349, "end": 387.519, "lines": ["Plus bas, les points à vérifier."]}, {"start": 387.569, "end": 389.465, "lines": ["Puis des questions", "pour l'entretien,"]}, {"start": 389.465, "end": 392.152, "lines": ["comme : « L'objectif formulé", "au dernier rendez-vous"]}, {"start": 392.152, "end": 395.879, "lines": ["est-il toujours d'actualité ? »", "Une question aide la conversation."]}, {"start": 396.049, "end": 398.529, "lines": ["Elle ne conclut rien", "sur la situation de Camille."]}, {"start": 398.569, "end": 400.559, "lines": ["Étape sept : la correction."]}, {"start": 400.809, "end": 402.679, "lines": ["Sophie voit d'où", "vient chaque élément."]}, {"start": 402.679, "end": 407.011, "lines": ["Elle retire une question peu pertinente,", "corrige la date de la dernière revue,"]}, {"start": 407.011, "end": 408.463, "lines": ["puis valide sa version."]}, {"start": 408.503, "end": 411.929, "lines": ["C'est Sophie qui mène le rendez-vous", "et interprète les réponses."]}, {"start": 411.969, "end": 416.389, "lines": ["Étape huit : le rendez-vous,", "de quatorze heures à quinze heures dix."]}, {"start": 416.429, "end": 417.458, "lines": ["Pas d'écran d'IA :"]}, {"start": 417.458, "end": 421.139, "lines": ["la conversation appartient", "à la cliente et à sa conseillère."]}, {"start": 421.229, "end": 424.179, "lines": ["Étape neuf :", "le brouillon de compte rendu."]}, {"start": 424.229, "end": 426.963, "lines": ["À quinze heures dix,", "Sophie saisit ses notes,"]}, {"start": 426.963, "end": 430.651, "lines": ["ou une transcription si celle-ci", "est autorisée et encadrée."]}, {"start": 430.691, "end": 434.282, "lines": ["L'agent sépare quatre choses :", "les faits rapportés par la cliente,"]}, {"start": 434.282, "end": 435.534, "lines": ["les questions ouvertes,"]}, {"start": 435.534, "end": 439.539, "lines": ["les décisions réellement prises", "par Sophie, et les actions proposées."]}, {"start": 439.589, "end": 443.615, "lines": ["Il signale une phrase ambiguë :", "« revoir le dossier le mois prochain »."]}, {"start": 443.655, "end": 446.419, "lines": ["Revoir quoi, avec qui,", "à quelle date ?"]}, {"start": 446.529, "end": 448.679, "lines": ["Il ne complète pas", "la promesse de lui-même."]}, {"start": 448.749, "end": 450.819, "lines": ["Étape dix : la validation."]}, {"start": 450.989, "end": 454.299, "lines": ["Sophie précise : un point", "téléphonique dans quatre semaines,"]}, {"start": 454.299, "end": 455.679, "lines": ["qu'elle mènera elle-même."]}, {"start": 455.679, "end": 458.059, "lines": ["Puis elle valide le compte rendu."]}, {"start": 458.169, "end": 460.983, "lines": ["Étape onze :", "les tâches et le suivi."]}, {"start": 461.023, "end": 465.369, "lines": ["L'agent propose deux tâches,", "avec responsable et échéance à confirmer."]}, {"start": 465.409, "end": 469.369, "lines": ["Une fois validées par Sophie, elles", "rejoignent l'outil de suivi autorisé."]}, {"start": 469.409, "end": 471.569, "lines": ["Un message à Camille", "reste un brouillon."]}, {"start": 471.609, "end": 475.329, "lines": ["Sophie contrôle le destinataire,", "le contenu et l'envoi."]}, {"start": 475.369, "end": 476.999, "lines": ["Rien ne part sans son clic."]}, {"start": 477.089, "end": 481.219, "lines": ["Sur les huit heures de ce bloc, l'objectif", "de test est d'en récupérer quatre."]}, {"start": 481.263, "end": 483.379, "lines": ["C'est un gain cible,", "pas un résultat."]}, {"start": 483.379, "end": 485.844, "lines": ["On mesurera le temps", "avant et après,"]}, {"start": 485.844, "end": 490.189, "lines": ["les corrections, les erreurs,", "et l'utilité réelle des briefs."]}, {"start": 490.229, "end": 495.519, "lines": ["Premier jalon, volontairement petit :", "trois briefs, puis une décision de Sophie."]}, {"start": 495.609, "end": 498.719, "lines": ["Continuer, ajuster,", "ou retirer l'accès."]}, {"start": 500.096, "end": 501.186, "lines": ["Deuxième scène."]}, {"start": 501.276, "end": 503.326, "lines": ["Mercredi, dix heures vingt."]}, {"start": 503.436, "end": 507.056, "lines": ["Léa prépare plusieurs dossiers pour des", "rendez-vous et une revue périodique."]}, {"start": 507.096, "end": 510.999, "lines": ["Elle parcourt les répertoires, compare", "les fichiers aux listes du cabinet,"]}, {"start": 510.999, "end": 515.206, "lines": ["cherche des dates, et fait trancher", "les cas incertains par Sophie ou Karim."]}, {"start": 515.256, "end": 519.066, "lines": ["Dans notre simulation, ce travail", "représente neuf heures par semaine."]}, {"start": 519.216, "end": 522.786, "lines": ["Première limite : l'agent n'invente", "pas les règles de contrôle."]}, {"start": 522.916, "end": 526.946, "lines": ["La liste applicable vient du cabinet,", "validée par la personne compétente."]}, {"start": 527.076, "end": 530.618, "lines": ["On vérifie aussi le cadre d'accès", "aux données : quelles sources,"]}, {"start": 530.618, "end": 533.164, "lines": ["quelles personnes habilitées,", "quelle finalité,"]}, {"start": 533.164, "end": 536.126, "lines": ["quel sous-traitant éventuel,", "quelle conservation."]}, {"start": 536.356, "end": 540.051, "lines": ["Pour un dossier sélectionné,", "l'agent lit la liste approuvée,"]}, {"start": 540.051, "end": 542.823, "lines": ["inventorie seulement", "les documents autorisés,"]}, {"start": 542.823, "end": 548.076, "lines": ["et range chaque ligne en quatre colonnes :", "présent, absent, ambigu, ou non vérifié."]}, {"start": 548.116, "end": 551.93, "lines": ["Supposons un justificatif présent,", "mais dont la date est illisible."]}, {"start": 551.97, "end": 555.306, "lines": ["L'agent ne le marque ni", "« valide », ni « périmé »."]}, {"start": 555.416, "end": 556.672, "lines": ["Il le classe en ambigu,"]}, {"start": 556.672, "end": 560.146, "lines": ["et montre le document source", "avec la raison du signalement."]}, {"start": 560.276, "end": 564.206, "lines": ["Léa retrouve une meilleure version,", "ou demande à Sophie quelle suite donner."]}, {"start": 564.296, "end": 567.701, "lines": ["Pour une revue périodique,", "il compare avec la dernière revue :"]}, {"start": 567.701, "end": 571.906, "lines": ["éléments nouveaux, inchangés,", "pièces à examiner, contrôles sans réponse."]}, {"start": 571.956, "end": 574.132, "lines": ["Si une information", "essentielle manque,"]}, {"start": 574.132, "end": 576.616, "lines": ["l'écran indique :", "décision humaine requise."]}, {"start": 576.656, "end": 580.706, "lines": ["Jamais de badge « dossier conforme »", "sur la seule base de sa lecture."]}, {"start": 580.83, "end": 584.036, "lines": ["C'est essentiel pour la connaissance", "client et la vigilance."]}, {"start": 584.076, "end": 585.635, "lines": ["Selon les activités exercées,"]}, {"start": 585.635, "end": 589.056, "lines": ["le professionnel applique", "les exigences qui lui sont propres."]}, {"start": 589.096, "end": 592.887, "lines": ["Pour le conseil en investissements", "financiers, l'AMF décrit notamment"]}, {"start": 592.887, "end": 596.624, "lines": ["les informations à recueillir avant", "de conseiller, et la déclaration"]}, {"start": 596.624, "end": 600.976, "lines": ["d'adéquation remise au client avant", "la réalisation de l'opération conseillée."]}, {"start": 601.016, "end": 602.798, "lines": ["Pour les professionnels", "assujettis,"]}, {"start": 602.798, "end": 606.67, "lines": ["les obligations de vigilance suivent", "une approche fondée sur les risques."]}, {"start": 606.71, "end": 609.478, "lines": ["L'agent aide à préparer", "et à retrouver des éléments,"]}, {"start": 609.478, "end": 611.486, "lines": ["sans statuer sur leur suffisance."]}, {"start": 611.656, "end": 615.356, "lines": ["Et cette vidéo n'est pas un modèle", "universel de dossier réglementaire."]}, {"start": 615.396, "end": 619.181, "lines": ["Après la revue, un journal conserve", "les sources consultées, la version"]}, {"start": 619.181, "end": 623.236, "lines": ["du résultat, la correction de Léa,", "la validation de Sophie et l'horodatage,"]}, {"start": 623.236, "end": 625.866, "lines": ["selon les règles", "de conservation du cabinet."]}, {"start": 626.036, "end": 628.507, "lines": ["Mais un journal technique", "n'est pas, à lui seul,"]}, {"start": 628.507, "end": 631.546, "lines": ["la preuve que les obligations", "réglementaires sont remplies."]}, {"start": 631.546, "end": 635.348, "lines": ["Hypothèse : ramener ce bloc", "de neuf à six heures par semaine,"]}, {"start": 635.348, "end": 637.356, "lines": ["soit trois heures récupérées."]}, {"start": 637.396, "end": 641.099, "lines": ["Le pilote suivra aussi les faux positifs,", "les vrais manques détectés,"]}, {"start": 641.099, "end": 644.086, "lines": ["et les situations correctement", "laissées à l'équipe."]}, {"start": 645.413, "end": 646.523, "lines": ["Troisième scène."]}, {"start": 646.613, "end": 648.793, "lines": ["Jeudi, seize heures quarante."]}, {"start": 648.833, "end": 649.682, "lines": ["Une cliente écrit :"]}, {"start": 649.682, "end": 653.063, "lines": ["« Pouvez-vous me rappeler ce que nous", "avions convenu pour la suite ? »"]}, {"start": 653.213, "end": 656.108, "lines": ["Léa cherche le dernier compte", "rendu, vérifie la tâche,"]}, {"start": 656.108, "end": 658.613, "lines": ["puis demande à Karim", "si l'action est faite."]}, {"start": 658.653, "end": 662.747, "lines": ["En parallèle, un prospect attend", "un retour et deux échéances approchent."]}, {"start": 662.787, "end": 664.935, "lines": ["L'agent de service", "classe la demande,"]}, {"start": 664.935, "end": 668.244, "lines": ["puis rassemble les seuls", "éléments autorisés : le message,"]}, {"start": 668.244, "end": 671.213, "lines": ["le compte rendu validé,", "la tâche et son statut."]}, {"start": 671.253, "end": 672.533, "lines": ["Il prépare une fiche."]}, {"start": 672.573, "end": 674.053, "lines": ["Voici l'engagement retrouvé."]}, {"start": 674.093, "end": 674.863, "lines": ["Voici sa source."]}, {"start": 674.863, "end": 676.533, "lines": ["Voici l'état connu."]}, {"start": 676.573, "end": 678.933, "lines": ["Et voici ce que nous", "ne savons pas encore."]}, {"start": 678.973, "end": 681.203, "lines": ["Il peut rédiger", "un brouillon de réponse."]}, {"start": 681.313, "end": 683.498, "lines": ["Ici, la tâche n'a pas", "de statut fiable :"]}, {"start": 683.498, "end": 686.643, "lines": ["le brouillon n'affirme donc", "pas qu'elle est terminée."]}, {"start": 686.733, "end": 690.153, "lines": ["Karim vérifie, complète,", "puis décide de l'envoi."]}, {"start": 690.193, "end": 693.763, "lines": ["Seul Karim dispose du bouton", "« vérifier et envoyer »."]}, {"start": 693.807, "end": 695.901, "lines": ["L'agent n'a qu'un bouton :", "« préparer »."]}, {"start": 696.253, "end": 697.783, "lines": ["Même logique pour un prospect."]}, {"start": 697.847, "end": 700.417, "lines": ["L'agent propose une fiche", "de qualification à partir"]}, {"start": 700.417, "end": 704.601, "lines": ["du formulaire et des échanges autorisés,", "des questions pour un premier rendez-vous,"]}, {"start": 704.601, "end": 706.333, "lines": ["et une relance contextualisée."]}, {"start": 706.373, "end": 708.505, "lines": ["Le conseiller choisit", "de prendre contact,"]}, {"start": 708.505, "end": 711.813, "lines": ["d'accepter ou non le prospect,", "et d'envoyer chaque message."]}, {"start": 711.853, "end": 714.783, "lines": ["Aucun score automatique", "de « valeur » de la personne."]}, {"start": 714.933, "end": 718.607, "lines": ["Le lundi suivant, à neuf heures,", "Sophie ouvre une vue de pilotage."]}, {"start": 718.647, "end": 722.686, "lines": ["L'agent a rapproché agenda, tâches", "et statuts du CRM en quatre listes :"]}, {"start": 722.686, "end": 726.213, "lines": ["rendez-vous à préparer,", "engagements sans responsable confirmé,"]}, {"start": 726.213, "end": 727.407, "lines": ["échéances à vérifier,"]}, {"start": 727.407, "end": 731.503, "lines": ["et dossiers sans action récente,", "selon une règle choisie par le cabinet."]}, {"start": 731.503, "end": 733.993, "lines": ["Chaque signal comporte une raison."]}, {"start": 734.033, "end": 738.159, "lines": ["Un dossier sans activité récente", "n'est pas étiqueté « client négligé »."]}, {"start": 738.333, "end": 742.178, "lines": ["Sophie répond : « celui-ci", "attend volontairement une date »,"]}, {"start": 742.178, "end": 746.6, "lines": ["« celui-là mérite un appel »,", "« cette donnée du CRM est incorrecte »."]}, {"start": 746.6, "end": 748.113, "lines": ["C'est elle qui arbitre."]}, {"start": 748.153, "end": 752.296, "lines": ["Notre hypothèse : ramener ce bloc", "de sept à quatre heures par semaine,"]}, {"start": 752.296, "end": 754.193, "lines": ["soit trois heures récupérées."]}, {"start": 754.233, "end": 756.888, "lines": ["On compte aussi les alertes", "utiles ou écartées,"]}, {"start": 756.888, "end": 759.883, "lines": ["les brouillons corrigés", "et les engagements retrouvés."]}, {"start": 759.883, "end": 763.234, "lines": ["Si le tableau produit du bruit,", "on réduit son périmètre :"]}, {"start": 763.234, "end": 766.423, "lines": ["un cockpit que personne", "n'ouvre n'est pas un gain."]}, {"start": 767.823, "end": 770.842, "lines": ["Sophie pose alors la bonne question :", "« Pour préparer tout ça,"]}, {"start": 770.842, "end": 774.013, "lines": ["l'agent doit-il lire tous mes", "mails et tous mes dossiers ? »"]}, {"start": 774.203, "end": 776.083, "lines": ["La réponse de la mission est non."]}, {"start": 776.123, "end": 778.394, "lines": ["Chaque workflow", "a un objectif défini,"]}, {"start": 778.394, "end": 782.753, "lines": ["des sources approuvées, des droits", "limités et des personnes habilitées."]}, {"start": 782.753, "end": 785.828, "lines": ["Source autorisée,", "accès limité, préparation,"]}, {"start": 785.828, "end": 788.983, "lines": ["validation humaine,", "destination autorisée."]}, {"start": 789.023, "end": 791.208, "lines": ["Avant d'utiliser", "des données clients,"]}, {"start": 791.208, "end": 795.637, "lines": ["le cabinet examine ses responsabilités,", "ses contrats avec les prestataires,"]}, {"start": 795.637, "end": 799.003, "lines": ["la sécurité, la conservation", "et les éventuels transferts."]}, {"start": 799.003, "end": 802.47, "lines": ["Héberger un modèle soi-même,", "ou choisir un modèle open source,"]}, {"start": 802.47, "end": 805.103, "lines": ["ne suffit pas à rendre", "un traitement conforme."]}, {"start": 805.143, "end": 809.193, "lines": ["La CNIL rappelle notamment l'importance", "d'encadrer la sous-traitance,"]}, {"start": 809.193, "end": 813.553, "lines": ["de protéger les données et de garder", "une intervention humaine adaptée."]}, {"start": 813.603, "end": 816.093, "lines": ["Concrètement,", "l'agent sait s'arrêter."]}, {"start": 816.157, "end": 820.863, "lines": ["S'il ne retrouve pas la source d'un fait,", "il écrit : information non vérifiée."]}, {"start": 820.903, "end": 824.393, "lines": ["Si une pièce est illisible,", "il demande une vérification."]}, {"start": 824.603, "end": 829.883, "lines": ["Si une demande implique une interprétation", "patrimoniale ou une décision de conseil,"]}, {"start": 829.883, "end": 831.443, "lines": ["il la transmet au CGP."]}, {"start": 831.483, "end": 833.283, "lines": ["Il ne recommande aucun produit."]}, {"start": 833.323, "end": 835.863, "lines": ["Il ne détermine pas seul", "un profil de risque."]}, {"start": 835.903, "end": 838.003, "lines": ["Il ne déclare pas", "un dossier conforme."]}, {"start": 838.043, "end": 840.323, "lines": ["Il ne contacte personne", "automatiquement."]}, {"start": 840.363, "end": 843.257, "lines": ["Il ne modifie pas un engagement", "client sans validation."]}, {"start": 843.297, "end": 844.439, "lines": ["C'est pourquoi un vrai"]}, {"start": 844.439, "end": 848.363, "lines": ["déploiement commence avec des données", "de démonstration et un accès limité."]}, {"start": 848.403, "end": 849.335, "lines": ["Les données réelles"]}, {"start": 849.335, "end": 853.413, "lines": ["arrivent seulement après revue du cadre", "applicable et autorisation du cabinet."]}, {"start": 854.813, "end": 858.413, "lines": ["Reprenons nos chiffres, sans additionner", "des promesses incompatibles."]}, {"start": 858.453, "end": 863.233, "lines": ["Préparation des rendez-vous et suivi :", "huit heures avant, quatre visées après."]}, {"start": 863.273, "end": 864.813, "lines": ["Quatre heures à confirmer."]}, {"start": 864.853, "end": 868.193, "lines": ["Contrôles et revues :", "neuf heures avant, six visées."]}, {"start": 868.233, "end": 869.903, "lines": ["Trois heures à confirmer."]}, {"start": 869.953, "end": 874.283, "lines": ["Relation client et pilotage :", "sept heures avant, quatre visées."]}, {"start": 874.393, "end": 876.103, "lines": ["Trois heures à confirmer."]}, {"start": 876.153, "end": 880.523, "lines": ["Avant : huit plus neuf plus sept,", "vingt-quatre heures."]}, {"start": 880.523, "end": 886.463, "lines": ["Après, visé : quatre plus six", "plus quatre, quatorze heures."]}, {"start": 886.527, "end": 889.183, "lines": ["L'écart visé :", "dix heures par semaine."]}, {"start": 889.313, "end": 891.163, "lines": ["Dix heures de capacité", "potentielle,"]}, {"start": 891.163, "end": 894.163, "lines": ["à condition que les gains", "résistent à l'observation."]}, {"start": 894.333, "end": 896.603, "lines": ["La mesure réelle reste à établir."]}, {"start": 896.793, "end": 898.719, "lines": ["Sur une année,", "dix heures multipliées"]}, {"start": 898.719, "end": 902.823, "lines": ["par quarante-six semaines travaillées", "donnent quatre cent soixante heures."]}, {"start": 902.893, "end": 904.727, "lines": ["À titre d'illustration seulement,"]}, {"start": 904.727, "end": 908.616, "lines": ["avec une heure interne valorisée", "à soixante euros, cela représenterait"]}, {"start": 908.616, "end": 912.423, "lines": ["vingt-sept mille six cents euros", "de capacité théorique annuelle."]}, {"start": 912.493, "end": 917.353, "lines": ["Ce n'est ni une économie de trésorerie", "acquise, ni un revenu additionnel."]}, {"start": 917.393, "end": 918.471, "lines": ["Capacité théorique,"]}, {"start": 918.471, "end": 922.863, "lines": ["économies encaissées et chiffre", "d'affaires sont trois choses différentes."]}, {"start": 922.993, "end": 925.734, "lines": ["Il faut encore déduire", "le temps de contrôle humain,"]}, {"start": 925.734, "end": 929.263, "lines": ["le coût des outils, la maintenance", "et les erreurs à corriger."]}, {"start": 930.663, "end": 932.373, "lines": ["Quel agent déployer en premier ?"]}, {"start": 932.463, "end": 935.617, "lines": ["Ici, je commencerais", "par la préparation d'un rendez-vous,"]}, {"start": 935.617, "end": 940.293, "lines": ["sur trois briefs : un périmètre étroit,", "compréhensible par Sophie, et mesurable."]}, {"start": 940.363, "end": 943.006, "lines": ["Si les briefs sont utiles", "et les accès maîtrisés,"]}, {"start": 943.006, "end": 946.997, "lines": ["on ajoute le compte rendu et les tâches,", "puis les contrôles documentaires,"]}, {"start": 946.997, "end": 949.513, "lines": ["et enfin la relation", "client et le cockpit."]}, {"start": 949.723, "end": 951.553, "lines": ["Voici le planning proposé."]}, {"start": 951.603, "end": 953.955, "lines": ["Semaines un et deux :", "diagnostic réel,"]}, {"start": 953.955, "end": 958.413, "lines": ["chronométrage, cartographie des données,", "et choix d'un seul cas d'usage."]}, {"start": 958.413, "end": 962.548, "lines": ["Semaines trois à cinq :", "construction et test du premier workflow,"]}, {"start": 962.548, "end": 966.843, "lines": ["d'abord sur des données fictives,", "puis sur un périmètre autorisé."]}, {"start": 966.883, "end": 969.693, "lines": ["Trois briefs,", "relus intégralement par Sophie."]}, {"start": 969.763, "end": 974.533, "lines": ["Semaines six à huit : décision", "d'étendre, d'ajuster ou d'arrêter."]}, {"start": 974.663, "end": 978.458, "lines": ["Les autres agents n'entrent dans le pilote", "que si le premier a fait ses preuves"]}, {"start": 978.458, "end": 980.293, "lines": ["et si leurs accès sont approuvés."]}, {"start": 980.363, "end": 984.193, "lines": ["Huit semaines ne promettent donc pas trois", "agents achevés dans tous les cabinets."]}, {"start": 984.193, "end": 986.402, "lines": ["Le résultat recherché", "n'est pas un cabinet"]}, {"start": 986.402, "end": 989.697, "lines": ["où l'intelligence artificielle", "parle à la place du conseiller."]}, {"start": 989.737, "end": 993.593, "lines": ["C'est un cabinet où le conseiller", "retrouve le contexte, voit les manques,"]}, {"start": 993.593, "end": 996.223, "lines": ["et décide avec moins", "de recherches dispersées."]}, {"start": 996.263, "end": 998.947, "lines": ["Si vous dirigez un cabinet", "de gestion de patrimoine,"]}, {"start": 998.947, "end": 1000.548, "lines": ["le point de départ est simple :"]}, {"start": 1000.548, "end": 1003.143, "lines": ["montrez-nous un dossier", "et une semaine réelle."]}, {"start": 1003.183, "end": 1006.927, "lines": ["On identifiera ce qui mérite d'être", "préparé, ce qui doit rester humain,"]}, {"start": 1006.927, "end": 1009.723, "lines": ["et ce qu'un pilote permettrait", "réellement de mesurer."]}, {"start": 1009.723, "end": 1011.377, "lines": ["Agentic Wealth."]}, {"start": 1011.377, "end": 1012.603, "lines": ["L'agent prépare."]}, {"start": 1012.643, "end": 1015.473, "lines": ["Le CGP valide et décide."]}], "voice": "ElevenLabs, voix Bastien (eleven_multilingual_v2)", "duration": 1018.416};
